// 命令接口：execute 执行，undo 回滚
interface Command {
    void execute();
    void undo();
}

// 接收者：真正干活的对象
class Light {
    void on() { System.out.println("灯亮"); }
    void off() { System.out.println("灯灭"); }
}

// 具体命令：持有 Receiver，execute 调用 on，undo 调用 off
class LightOnCommand implements Command {
    private final Light light;
    LightOnCommand(Light light) { this.light = light; }
    public void execute() { light.on(); }
    public void undo() { light.off(); }
}

// 宏命令：组合多个子命令，execute 正序执行，undo 逆序回滚
class MacroCommand implements Command {
    private final java.util.List<Command> cmds;
    MacroCommand(java.util.List<Command> cmds) { this.cmds = cmds; }
    public void execute() { cmds.forEach(Command::execute); }
    public void undo() {
        for (int i = cmds.size() - 1; i >= 0; i--) cmds.get(i).undo();
    }
}

// 调用者：维护 undo 栈和 redo 栈
class Remote {
    private final java.util.Deque<Command> undoStack = new java.util.ArrayDeque<>();
    private final java.util.Deque<Command> redoStack = new java.util.ArrayDeque<>();

    void submit(Command c) {
        c.execute();
        undoStack.push(c);
        redoStack.clear(); // 新操作清空 redo 栈
    }

    void undo() {
        if (!undoStack.isEmpty()) {
            Command c = undoStack.pop();
            c.undo();
            redoStack.push(c);
        }
    }

    void redo() {
        if (!redoStack.isEmpty()) {
            Command c = redoStack.pop();
            c.execute();
            undoStack.push(c);
        }
    }
}
